                                "tabIndex": null,
                                "template": {
                                    "value": "",
                                    "funcBody": "//UIs available depending on chart selected\nlet chartTitle = {{textInputChartTitle.value}}\nlet xAxisTitle = {{textInputXAxisTitle.value}}\nlet yAxisTitle = {{textInputYAxisTitle.value}}\nlet isLegendVisible = {{checkboxLegendVisible.value}}\n    \nreturn { \n\"line\":{\n  \"title\": {\n    \"text\": chartTitle,\n    \"font\": {\n      \"color\": \"#3D3D3D\",\n      \"size\": 16\n    }\n  },\n  \"font\": {\n    \"family\": \"Inter\",\n    \"color\": \"#979797\"\n  },\n  \"showlegend\": isLegendVisible,\n  \"legend\": {\n    \"xanchor\": \"center\",\n    \"x\": 0.45,\n    \"y\": -0.2,\n    \"orientation\": \"h\"\n  },\n  \"margin\": {\n    \"l\": 16,\n    \"r\": 24,\n    \"t\": 24,\n    \"b\": 32,\n    \"pad\": 2\n  },\n  \"hovermode\": \"closest\",\n  \"hoverlabel\": {\n    \"bgcolor\": \"#000\",\n    \"bordercolor\": \"#000\",\n    \"font\": {\n      \"color\": \"#fff\",\n      \"family\": \"Inter\",\n      \"size\": 12\n    }\n  },\n  \"clickmode\": \"select+event\",\n  \"dragmode\": \"select\",\n  \"xaxis\": {\n    \"title\": {\n      \"text\": xAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"-\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"gridcolor\": \"#fff\",\n    \"zerolinecolor\": \"#fff\"\n  },\n  \"yaxis\": {\n    \"title\": {\n      \"text\": yAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"linear\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"zerolinecolor\": \"#DEDEDE\"\n  }\n},\n\"bar\":   {\n  \"title\": {\n    \"text\": chartTitle,\n    \"font\": {\n      \"color\": \"#3D3D3D\",\n      \"size\": 16\n    }\n  },\n  \"font\": {\n    \"family\": \"Inter\",\n    \"color\": \"#979797\"\n  },\n  \"showlegend\": isLegendVisible,\n  \"legend\": {\n    \"xanchor\": \"center\",\n    \"x\": 0.45,\n    \"y\": -0.2,\n    \"orientation\": \"h\"\n  },\n  \"margin\": {\n    \"l\": 16,\n    \"r\": 24,\n    \"t\": 24,\n    \"b\": 32,\n    \"pad\": 2\n  },\n  \"hovermode\": \"closest\",\n  \"hoverlabel\": {\n    \"bgcolor\": \"#000\",\n    \"bordercolor\": \"#000\",\n    \"font\": {\n      \"color\": \"#fff\",\n      \"family\": \"Inter\",\n      \"size\": 12\n    }\n  },\n  \"clickmode\": \"select+event\",\n  \"dragmode\": \"select\",\n  \"xaxis\": {\n    \"title\": {\n      \"text\": xAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"-\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"gridcolor\": \"#fff\",\n    \"zerolinecolor\": \"#fff\"\n  },\n  \"yaxis\": {\n    \"title\": {\n      \"text\": yAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"linear\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"zerolinecolor\": \"#DEDEDE\"\n  }\n},\n\"pie\" : {\n  \"title\": {\n    \"text\": chartTitle,\n    \"font\": {\n      \"color\": \"#3D3D3D\",\n      \"size\": 16\n    }\n  },\n  \"font\": {\n    \"family\": \"Inter\",\n    \"color\": \"#979797\"\n  },\n  \"showlegend\": isLegendVisible,\n  \"legend\": {\n    \"xanchor\": \"center\",\n    \"x\": 0.45,\n    \"y\": -0.2,\n    \"orientation\": \"h\"\n  },\n  \"margin\": {\n    \"l\": 16,\n    \"r\": 24,\n    \"t\": 24,\n    \"b\": 32,\n    \"pad\": 2\n  },\n  \"hovermode\": \"closest\",\n  \"hoverlabel\": {\n    \"bgcolor\": \"#000\",\n    \"bordercolor\": \"#000\",\n    \"font\": {\n      \"color\": \"#fff\",\n      \"family\": \"Inter\",\n      \"size\": 12\n    }\n  },\n  \"clickmode\": \"select+event\",\n  \"dragmode\": \"select\"\n},\n\"scatter\": {\n  \"title\": {\n    \"text\": chartTitle,\n    \"font\": {\n      \"color\": \"#3D3D3D\",\n      \"size\": 16\n    }\n  },\n  \"font\": {\n    \"family\": \"Inter\",\n    \"color\": \"#979797\"\n  },\n  \"showlegend\": isLegendVisible,\n  \"legend\": {\n    \"xanchor\": \"center\",\n    \"x\": 0.45,\n    \"y\": -0.2,\n    \"orientation\": \"h\"\n  },\n  \"margin\": {\n    \"l\": 16,\n    \"r\": 24,\n    \"t\": 24,\n    \"b\": 32,\n    \"pad\": 2\n  },\n  \"hovermode\": \"closest\",\n  \"hoverlabel\": {\n    \"bgcolor\": \"#000\",\n    \"bordercolor\": \"#000\",\n    \"font\": {\n      \"color\": \"#fff\",\n      \"family\": \"Inter\",\n      \"size\": 12\n    }\n  },\n  \"clickmode\": \"select+event\",\n  \"dragmode\": \"select\",\n  \"xaxis\": {\n    \"title\": {\n      \"text\": xAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"-\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"gridcolor\": \"#fff\",\n    \"zerolinecolor\": \"#fff\"\n  },\n  \"yaxis\": {\n    \"title\": {\n      \"text\": yAxisTitle,\n      \"standoff\": 6,\n      \"font\": {\n        \"size\": 12\n      }\n    },\n    \"type\": \"linear\",\n    \"tickformat\": \"\",\n    \"automargin\": true,\n    \"fixedrange\": true,\n    \"zerolinecolor\": \"#DEDEDE\"\n  }\n}\n       }"
                                },
