                                    "query": "let formData = listViewDataFields3.data\n\nlet dataFieldsData = {\n  \"fields\": []\n};\n\n// loop through the listView data and grab the current value for each component\nfor (let i = 0; i < formData.length; i++) {\n    let field = formData[i].textDataSetName3.substring(6);\n    let chartType = formData[i].selectDataSetChartType3;\n    let aggregate = formData[i].selectDataSetAggMethod3;\n    let marker = formData[i].selectMode3;\n    let color = formData[i].colorInputDataSet3;\n  \n  dataFieldsData.fields.push({\n    \"field\": field,\n    \"chartType\": chartType,\n    \"aggregate\": aggregate,\n    \"marker\": marker,\n    \"color\": color\n  });\n}\n\nreturn dataFieldsData;",
